/**
 * Fan-out honours preferences and the digest flag.
 *
 * Owner C implements `@/server/services/notification-service`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as issueService from "@/server/services/issue-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import {
  listNotifications,
  notify,
  resolveChannels,
} from "@/server/services/notification-service";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("notify", "growth");
});

afterAll(() => {
  cleanup();
});

describe("services/notification-service", () => {
  // comment.created with mentions produces one comment_mention per mentioned user.
  it("creates one notification per mentioned user", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions issue" }),
    );

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: issue.createdAt,
      commentId: "cmt-mentions-1" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.admin, tenant.userIds.viewer],
    });

    const forAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    const forViewer = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });

    expect(forAdmin.items).toHaveLength(1);
    expect(forViewer.items).toHaveLength(1);
    expect(forAdmin.items[0]?.kind).toBe("comment_mention");
  });

  // The actor who caused the event is not notified about their own action.
  it("does not notify the actor about their own action", async () => {
    const rows = await notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.member, tenant.userIds.admin],
      {
        title: "New comment",
        body: "Someone commented",
        href: "/issues/x",
        actorId: tenant.userIds.member,
      },
    );

    expect(rows).toHaveLength(1);
    expect(rows[0]?.recipientId).toBe(tenant.userIds.admin);
  });

  // NotificationPreference.email === false suppresses the email channel only.
  it("honours the per-kind email preference", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_assigned",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
      title: "Assigned",
      body: "You were assigned",
      href: "/issues/y",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toEqual(["in_app"]);
  });

  // digestOnly routes the entry to the digest instead of an immediate email.
  it("queues a digestOnly notification for the digest instead of sending", () => {
    const flagsWithDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "growth",
      role: null,
      overrides: undefined,
    };

    const channels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithDigest,
    );

    // The org's plan includes the digest_email flag, so the entry is still
    // routed to the "email" channel — it will go out with the digest run
    // rather than never leaving the in-app row.
    expect(channels).toEqual(["in_app", "email"]);
  });

  // isEnabled("digest_email", …) gates the digest channel by plan.
  it("skips the digest channel when the digest_email flag is off", () => {
    const flagsWithoutDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "free",
      role: null,
      overrides: undefined,
    };

    const digestOnlyChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithoutDigest,
    );

    // Without the plan flag, a digestOnly preference loses the email channel
    // entirely (the org has no digest run to defer it to).
    expect(digestOnlyChannels).toEqual(["in_app"]);

    // A non-digestOnly preference is unaffected by the flag.
    const immediateChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: false,
      },
      flagsWithoutDigest,
    );
    expect(immediateChannels).toEqual(["in_app", "email"]);
  });

  // in_app is always recorded, even when email delivery is suppressed.
  it("always records the in-app notification", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "member_joined",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "member_joined", [tenant.userIds.viewer], {
      title: "Member joined",
      body: "A member joined",
      href: "/settings/members",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toContain("in_app");

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["member_joined"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
  });

  // Notifications carry the org id and are only visible inside that tenant.
  it("scopes notifications to the recipient's organization", async () => {
    const other = await createTenant("notify-other", "growth");

    await notify(tenant.org.id, "member_joined", [tenant.userIds.owner], {
      title: "Member joined",
      body: "Welcome",
      href: "/settings/members",
      actorId: null,
    });

    await expect(
      listNotifications(other.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);
  });
});
/** Domain-error to `AppErrorShape` mapping for every error class. */
import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
  HTTP_STATUS_BY_CODE,
  fieldErrorsFromZod,
  isDomainError,
  toActionResult,
  toAppError,
} from "@/lib/errors";
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError, explain } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { OrgId } from "@/types/common";
import { makeActor, ORG_A, ORG_B } from "../helpers/factories";

const schema = z.object({
  title: z.string().min(3),
  estimate: z.number().int(),
});

function permissionError(): PermissionDeniedError {
  const actor = makeActor({ role: "viewer" });
  const resource = { kind: "organization", orgId: ORG_A } as const;
  return new PermissionDeniedError("org:delete", explain(actor, "org:delete", resource));
}

describe("lib/errors", () => {
  it("maps a permission denial to `forbidden` with the decision in meta", () => {
    const shape = toAppError(permissionError());
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.action).toBe("org:delete");
    expect(shape.meta?.reason).toBe("denied_by_role");
  });

  it("maps a tenant scope violation to `tenant_scope_violation`", () => {
    const shape = toAppError(new TenantScopeError(ORG_A, ORG_B));
    expect(shape.code).toBe("tenant_scope_violation");
    expect(shape.meta?.expectedOrgId).toBe(ORG_A);
    expect(shape.message).not.toContain(ORG_B as string);
  });

  it("maps a disabled feature to `forbidden` and names the flag", () => {
    const shape = toAppError(new FeatureDisabledError("webhooks"));
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.flag).toBe("webhooks");
  });

  it("maps double archiving to `conflict`", () => {
    const shape = toAppError(new AlreadyArchivedError("Issue", "01ISS"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta?.entity).toBe("Issue");
  });

  it("maps an invalid slug to `validation_failed` with a slug field error", () => {
    const shape = toAppError(new InvalidSlugError("Admin!", "is reserved"));
    expect(shape.code).toBe("validation_failed");
    expect(shape.fieldErrors?.slug?.[0]).toContain("is reserved");
  });

  it("maps a ZodError to field errors keyed by dotted path", () => {
    const parsed = schema.safeParse({ title: "no", estimate: 1.5 });
    expect(parsed.success).toBe(false);
    if (parsed.success) return;

    const fields = fieldErrorsFromZod(parsed.error);
    expect(Object.keys(fields).sort()).toEqual(["estimate", "title"]);
    expect(toAppError(parsed.error).code).toBe("validation_failed");
  });

  it("falls back to `internal_error` for an unknown throw", () => {
    expect(toAppError(new Error("boom")).code).toBe("internal_error");
    expect(toAppError("boom").code).toBe("internal_error");
    expect(toAppError("boom").message).toContain("Something went wrong");
  });

  it("recognises exactly the domain error classes", () => {
    expect(isDomainError(permissionError())).toBe(true);
    expect(isDomainError(new TenantScopeError(ORG_A, ORG_B))).toBe(true);
    expect(isDomainError(new InvalidSlugError("x", "too short"))).toBe(true);
    expect(isDomainError(new Error("boom"))).toBe(false);
    expect(isDomainError(null)).toBe(false);
  });

  it("gives every error code an HTTP status", () => {
    for (const [code, status] of Object.entries(HTTP_STATUS_BY_CODE)) {
      expect(status, code).toBeGreaterThanOrEqual(400);
    }
    expect(HTTP_STATUS_BY_CODE.rate_limited).toBe(429);
    expect(HTTP_STATUS_BY_CODE.plan_limit_exceeded).toBe(402);
  });

  it("wraps a failure as an ActionResult, never throwing", () => {
    const result = toActionResult(new AlreadyArchivedError("Project", "01PRJ"));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("conflict");
    expect(typeof result.submittedAt).toBe("string");
  });

  it("keeps a cross-tenant org id out of the user-facing message", () => {
    const other = "01HZZZDDDDDDDDDDDDDDDDDDDD" as OrgId;
    expect(toAppError(new TenantScopeError(ORG_A, other)).message).toBe(
      "That resource belongs to a different organization.",
    );
  });
});
