export async function listAncestorIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const db = getDb();
  const parentOf = (id: string) =>
    db
      .select({ id: issues.id, parentId: issues.parentId })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, id)))
      .get();

  const seen = new Set<string>([issueId]);
  const chain: IssueId[] = [];
  let nextId = parentOf(issueId)?.parentId ?? null;

  while (nextId !== null && !seen.has(nextId)) {
    const row = parentOf(nextId);
    if (!row) break;
    seen.add(row.id);
    chain.push(row.id as IssueId);
    nextId = row.parentId;
  }

  return chain;
}

