export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const below = await issueRepo.listDescendants(orgId, issue.id);
  const closed = below.filter((entry) =>
    CLOSED_ISSUE_STATUSES.includes(entry.issue.status),
  ).length;

  return { total: below.length, open: below.length - closed, closed };
}

/**
 * Loads a would-be parent: it must be a live issue of `projectId` in the
 * same workspace. An issue elsewhere is reported as not found.
 */
async function requireLiveParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const candidate = await issueRepo.findIssueById(orgId, parentId);
  const parent = requireFound(
    candidate?.projectId === projectId ? candidate : null,
    "Issue",
    parentId,
  );
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * Refuses a placement that would loop the tree or push anything below
 * `MAX_SUB_ISSUE_DEPTH`. `issueId` is null for an issue not created yet,
 * which has nothing below it.
