async function assertPlacement(
  orgId: OrgId,
  issueId: IssueId | null,
  parent: Issue | null,
): Promise<void> {
  const parentChain =
    parent === null
      ? []
      : [parent.id, ...(await issueRepo.listAncestorIds(orgId, parent.id))];

  if (issueId === null) {
    assertWithinDepth(parent?.id ?? "", parentChain.length, 0);
    return;
  }

  assertNoCycle(issueId, parentChain);

  const below = await issueRepo.listDescendants(orgId, issueId);
  const height = Math.max(0, ...below.map((entry) => entry.depth));
  assertWithinDepth(issueId, parentChain.length, height);
}""")
