  assertNotArchived("Issue", issue.id, issue);

  const below = await issueRepo.listDescendants(orgId, issue.id);
  const cascade = await issueRepo.archiveIssues(orgId, [
    issue.id,
    ...below.map((entry) => entry.issue.id),
  ]);
  const archived = requireFound(
    cascade.find((row) => row.id === issue.id),
    "Issue",
    issueId,
  );

  for (const row of cascade) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: row.id,
      projectId: row.projectId,
    });
  }

  return archived;
}

/**
 * Puts an issue under a parent issue of its project, or makes it a root again
 * with `parentId: null`. Its sub-issues move with it, so the depth check is
 * made against where the deepest of them would land.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const parent =
    input.parentId === null
      ? null
      : await requireLiveParent(input.orgId, before.projectId, input.parentId);
  await assertPlacement(input.orgId, before.id, parent);

  if (before.parentId === input.parentId) return before;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    before.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** The live direct sub-issues of an issue, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listSubIssues(orgId, issue.id);
}

/** Open/closed counts over every live issue below an issue, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const below = await issueRepo.listDescendants(orgId, issue.id);
  const closed = below.filter((entry) =>
    CLOSED_ISSUE_STATUSES.includes(entry.issue.status),
  ).length;

  return { total: below.length, open: below.length - closed, closed };
}

/**
 * Loads a would-be parent: it must be a live issue of `projectId` in the
 * same workspace. An issue elsewhere is reported as not found.
 */
async function requireLiveParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const candidate = await issueRepo.findIssueById(orgId, parentId);
  const parent = requireFound(
    candidate?.projectId === projectId ? candidate : null,
    "Issue",
    parentId,
  );
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * Board drag-and-drop. The index is presentation-only — the board renders by
 * `updated_at` — so a move is a status change plus a touch.
 */
export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

export async function getBoard(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "issue:read", projectResource(project));

  return issueRepo.listBoardColumns(orgId, projectId);
}

/** The ids from `parent` up to its root, the parent first; empty for none. */
async function parentChainOf(
  orgId: OrgId,
  parent: Issue | null,
): Promise<readonly IssueId[]> {
  if (parent === null) return [];
  return [parent.id, ...(await issueRepo.listAncestorIds(orgId, parent.id))];
}

/**
 * Refuses a placement that would loop the tree or push anything below
 * `MAX_SUB_ISSUE_DEPTH`. `issueId` is null for an issue about to be created,
 * which has nothing below it yet.
 */
async function assertPlacement(
  orgId: OrgId,
  issueId: IssueId | null,
  parent: Issue | null,
): Promise<void> {
  const chain = await parentChainOf(orgId, parent);

  if (issueId === null) {
    if (parent !== null) assertWithinDepth(parent.id, chain.length, 0);
    return;
  }

  assertNoCycle(issueId, chain);

  const below = await issueRepo.listDescendants(orgId, issueId);
  const height = below.reduce((deepest, entry) => Math.max(deepest, entry.depth), 0);
  assertWithinDepth(issueId, chain.length, height);
}

