    off2();
  });

  it("archives the subtree", async () => {
    const p = await mk("Archive root", null, t.userIds.admin);
    const c1 = await mk("Archive c1", p.id);
    const c2 = await mk("Archive c2", p.id);
    const g = await mk("Archive g", c1.id);
    await issueService.archiveIssue(t.actors.member, t.org.id, c2.id);
    const c2Before = await issueRepo.findIssueById(t.org.id, c2.id);
    const seen: string[] = [];
    const off = subscribe("issue.archived", (pl) => { seen.push(pl.issueId); });
    await new Promise((r) => setTimeout(r, 5));
    await issueService.archiveIssue(t.actors.member, t.org.id, p.id);
    off();
    expect(seen.sort()).toEqual([p.id, c1.id, g.id].sort());
    expect((await issueRepo.findIssueById(t.org.id, c2.id))?.archivedAt).toBe(c2Before?.archivedAt);
    expect((await issueRepo.findIssueById(t.org.id, g.id))?.archivedAt).not.toBeNull();
  });

  it("errors & schema", () => {
    const e = new IssueHierarchyError("x", "cycle");
    expect(toAppError(e).code).toBe("conflict");
    expect(isDomainError(e)).toBe(true);
    expect(e.code).toBe("conflict");
    expect(updateNotificationPreferenceSchema.safeParse({ orgId: t.org.id, userId: t.userIds.admin, kind: "sub_issues_completed", inApp: true, email: true, digestOnly: false }).success).toBe(true);
  });
});
